static my_bool extend_area_on_page(MARIA_HA *info,
                                   uchar *buff, uchar *dir,
                                   uint rownr,
                                   uint request_length,
                                   uint *empty_space, uint *ret_offset,
                                   uint *ret_length,
                                   my_bool head_page)
{
