void arena_reset(Arena* arena) {
    assert(arena != NULL);

    // Reset all blocks
    Block* block = arena->first;
    while (block) {
        block->used = 0;
        block = block->next;
    }

    // Reset arena stats
    arena->total_used = 0;
    arena->allocation_count = 0;
}

