	    /* Change link of previous upper-list key and save */
	    gpos2->ptr_to_rec=  ptr_to_rec2;
	    gpos2->next_key=    pos;
            gpos2->hash_of_key= hash_of_key2;
	    flag= (flag & LOWFIND) | (HIGHFIND | HIGHUSED);
	  }
